/* bop Aero embed: lease-rates
 * Built from components/lease-rates/src/ — DO NOT EDIT THIS FILE.
 * Edit the source or a data/<id>.json, then: python3 tools/build.py lease-rates
 * Aircraft in this build: sr22t
 */
(function () {
  var NAME = "lease-rates";
  var STYLE_ID = 'bopaero-style-' + NAME;
  var CSS = "/* ============================================================================\n   bop Aero embed design tokens \u2014 ONE definition, prepended to every component\n   by tools/build.py. Edit here, rebuild, and both components change together.\n\n   WHY THIS FILE EXISTS: the components previously declared almost no colours or\n   fonts, so every unspecified property silently inherited whatever Squarespace\n   supplied. That produced two customer-facing bugs in one week - orange footnotes\n   and an orange full-size usage note - each fixed one at a time. Tokens make the\n   whole class of bug impossible: nothing is left to inherit by accident.\n\n   Values are MEASURED from bopaero.com computed styles (2026-09-15), not guessed.\n   ========================================================================== */\n.bop-embed {\n  /* brand ------------------------------------------------------------------ */\n  --bop-orange:        #FF6700;\n  --bop-orange-ink:    #fff;\n  /* Derived, so a brand tweak needs one edit. color-mix keeps hover/active in\n     step with --bop-orange instead of drifting as hand-picked hex values. */\n  --bop-orange-hover:  color-mix(in srgb, var(--bop-orange) 88%, #000);\n  --bop-orange-soft:   color-mix(in srgb, var(--bop-orange) 12%, #fff);\n  --bop-navy:          #003767;\n  --bop-ink:           #282D30;\n\n  /* surfaces --------------------------------------------------------------- */\n  /* Raymond 2026-09-18: the calculator now wears the same navy the narrative\n     sections use (measured #003767 on the live pages), so the embed reads as part\n     of the page rather than a tan island in it. The card surface is only one step\n     lighter on purpose - enough to separate, not enough to stripe. */\n  --bop-panel:         #003767;   /* was #E9CEB0 tan */\n  /* Cards carry ALL the structure now. Raymond made the PRICING section the same\n     navy as the panel, so the panel's frame and shadow no longer separate anything\n     and #0A4478 was doing that job at 1.21:1 - which would vanish on a phone in\n     daylight. #0E4D8C is 1.41:1 against the panel: still one family, but each block\n     reads as its own surface. White stays 8.54:1 on it, muted 5.55:1, both AA. */\n  --bop-surface:       #0E4D8C;   /* cards sitting on the panel */\n  --bop-card:          #fff;      /* INPUT fields stay white: legible, and obviously editable */\n  --bop-line:          rgba(255,255,255,.18);\n\n  /* text ------------------------------------------------------------------- */\n  /* Contrast measured against the surface, not guessed: white 9.95:1, muted\n     6.46:1. Orange is 3.41:1 there, which is large-text only - so it is used for\n     buttons and marks, never for body copy. */\n  --bop-text:          #FFFFFF;\n  --bop-text-muted:    #C3D2E2;\n  --bop-label:         #DCE6F1;\n\n  /* type ------------------------------------------------------------------- */\n  --bop-font-head: \"Archivo Black\", \"Arial Black\", system-ui, sans-serif;\n  --bop-font-body: proxima-nova, \"Proxima Nova\", -apple-system, BlinkMacSystemFont,\n                   \"Segoe UI\", Helvetica, Arial, sans-serif;\n  --bop-head-ls:   -0.02em;       /* the site sets a tight negative tracking */\n\n  /* geometry --------------------------------------------------------------- */\n  --bop-radius:      10px;\n  --bop-radius-pill: 300px;       /* site buttons are full pills */\n  --bop-gap:         12px;\n\n  /* feedback --------------------------------------------------------------- */\n  --bop-focus:       var(--bop-navy);\n  --bop-warn-text:   #7a4a00;\n  --bop-warn-bg:     #fff6e5;\n  --bop-warn-edge:   #e8820c;\n\n  --bop-shadow:      0 1px 3px rgba(0,0,0,.10), 0 6px 18px rgba(0,0,0,.06);\n}\n\n/* Motion is opt-out, not opt-in. */\n@media (prefers-reduced-motion: reduce) {\n  .bop-embed *, .bop-embed *::before, .bop-embed *::after {\n    animation-duration: .001ms !important;\n    transition-duration: .001ms !important;\n  }\n}\n\n/* Inherits the page's own Squarespace type (h3, .sqsrte-large, body p) through the\n   classes in component.html; only the spacing the two original blocks had between\n   them is set here. */\n.bop-lease .bop-lease-rates + .bop-lease-notes { margin-top: 2em; }   /* both parts in one mount */\n.bop-lease [hidden] { display: none !important; }\n.bop-lease [data-f] { white-space: nowrap; }\n/* Squarespace text blocks drop the first element's top margin and the last\n   element's bottom margin; the parts are wrapped, so do the same here or the\n   block grows ~15px and the layout grid (and the photo beside it) grows with it. */\n.bop-lease .bop-lease-rates > :first-child, .bop-lease .bop-lease-notes > :first-child { margin-top: 0; }\n.bop-lease .bop-lease-rates > :last-child, .bop-lease .bop-lease-notes > :last-child { margin-bottom: 0; }\n";
  var HTML = "<!-- Leasing Program rates. Wording mirrors the two Squarespace blocks it replaced\n     (2026-10-07); every figure is filled from the costing. The Squarespace\n     classes keep the site's own type styles. Each mount shows one part\n     (data-part=\"rates\" or \"notes\") so the page layout is unchanged; no\n     data-part shows both. -->\n<div class=\"bop-lease sqs-html-content\">\n  <div class=\"bop-lease-rates\">\n  <h3><span class=\"sqsrte-text-color--black\"><span data-f=\"heading\"></span>\u00b9 \u00b2</span></h3>\n  <p class=\"sqsrte-large\"><strong>Monthly Lease </strong><span class=\"sqsrte-text-color--black\"><strong>\u00b9 \u00b2</strong></span></p>\n  <p class=\"sqsrte-large\"><span class=\"sqsrte-text-color--black\"><span data-f=\"monthly\"></span>, which includes <span data-f=\"hours\"></span> hours of use.</span></p>\n  <p class=\"sqsrte-large\"><strong>Hourly Lease \u00b2 \u00b3</strong></p>\n  <p class=\"sqsrte-large\"><span data-f=\"hourly\"></span> hr</p>\n  </div>\n  <div class=\"bop-lease-notes\">\n    <p><span class=\"sqsrte-text-color--black\"><em>\u00b9 Leases are one (1) month in length and prepaid in advance. Each lease includes <span data-f=\"hoursWords\"></span> hours of use. There are no penalties for exceeding the prepaid hours. Any flying that exceeds <span data-f=\"hours\"></span> hours will be billed at <span data-f=\"extra\"></span> per hour. All leases are exclusive between BOP AERO SERVICES LLC and the Lessee only.</em></span></p>\n    <p><span class=\"sqsrte-text-color--black\"><em>\u00b2 Variable costs, such as consumables (fuel/oilTKS), Crew (if applicable), and FBO Fees are not included.</em></span></p>\n    <p><span class=\"sqsrte-text-color--black\"><em>\u00b3 Hourly leases are granted on a case by case basis and are not intended for long term use. Contact bop Aero for more details. All leases are exclusive between BOP AERO SERVICES LLC and the Lessee only.</em></span></p>\n  </div>\n</div>\n";
  var DATA = {
"sr22t": {
"id": "sr22t",
"heading": "2026 Lease Rates",
"costing": {
"url": "https://sr22tprogram.bopaero.com/data/costing.json",
"_note": "Live source of truth: the SR22T costing's bridge aircraft lease terms (leaseMonthly, leaseIncludedHours, leaseExtraHourRate, leaseHourlyRate), edited in the private costing editor at https://sf50-costing.compilotrc.workers.dev/sr22t (Raymond 2026-10-07). The figures under `lease` are the FALLBACK shown first and if the costing can't load, kept current daily by tools/sync_costing.py. Edit rates in the editor, never here; the heading and wording are edited in the component."
},
"lease": {
"leaseMonthly": 5208,
"leaseIncludedHours": 14,
"leaseExtraHourRate": 372,
"leaseHourlyRate": 410
}
}
};

  function mount(el) {
    if (el.getAttribute('data-bopaero-mounted')) return;
    var id = el.getAttribute('data-aircraft');
    var spec = DATA[id];
    if (!spec) {
      console.error('[bopaero:' + NAME + '] unknown data-aircraft=' + JSON.stringify(id) +
                    '. Available: ' + Object.keys(DATA).join(', '));
      return;
    }
    el.setAttribute('data-bopaero-mounted', '1');
    if (CSS && !document.getElementById(STYLE_ID)) {
      var st = document.createElement('style');
      st.id = STYLE_ID; st.textContent = CSS;
      document.head.appendChild(st);
    }
    el.innerHTML = HTML;
    var root = el.querySelector('[data-calc-root]') || el;
    try { initLeaseRates(root, spec); }
    catch (e) { console.error('[bopaero:' + NAME + '] ' + id + ' failed', e); }
  }

  var DEPS = [];

  function loadDeps(done) {
    /* Squarespace blocks used to carry their own <script> tags for Leaflet etc.
       The stub cannot, so the loader pulls them itself — once per page, even if
       two components need the same library. */
    var pending = DEPS.length;
    if (!pending) return done();
    DEPS.forEach(function (d) {
      var sel = d.type === 'css' ? 'link[href="' + d.url + '"]' : 'script[src="' + d.url + '"]';
      var existing = document.querySelector(sel);
      if (existing) {
        if (d.type === 'css' || existing.getAttribute('data-loaded')) { if (!--pending) done(); return; }
        existing.addEventListener('load', function () { if (!--pending) done(); });
        return;
      }
      var el;
      if (d.type === 'css') {
        el = document.createElement('link'); el.rel = 'stylesheet'; el.href = d.url;
        document.head.appendChild(el); if (!--pending) done(); return;
      }
      el = document.createElement('script'); el.src = d.url; el.async = false;
      el.addEventListener('load', function () { el.setAttribute('data-loaded', '1'); if (!--pending) done(); });
      el.addEventListener('error', function () {
        console.error('[bopaero:' + NAME + '] dependency failed to load: ' + d.url);
        if (!--pending) done();
      });
      document.head.appendChild(el);
    });
  }

  function boot() {
    var els = document.querySelectorAll('[data-embed="' + NAME + '"][data-aircraft]');
    if (!els.length) {
      console.warn('[bopaero:' + NAME + '] no [data-embed="' + NAME + '"][data-aircraft] mount found');
      return;
    }
    loadDeps(function () { Array.prototype.forEach.call(els, mount); });
  }

  /* ── engine (verbatim from src/component.js) ───────────────────────── */
  /* ============================================================================
     bop Aero embed telemetry — aggregate only, prepended to every component.

     WHAT IT COLLECTS: how far down a page a visit scrolls, where clicks land as a
     coarse grid position, which named control was clicked, and a handful of
     calculator milestones. Plus page path and whether the viewport is phone-sized.

     WHAT IT DOES NOT COLLECT, BY DESIGN: no cookies, no visitor or session id, no
     fingerprint, no form values, no keystrokes, no session replay. Two visits are
     indistinguishable in the data. That is deliberate - it keeps this inside the
     "usage data / network activity" the existing privacy notice already describes,
     so no new processor and no policy redraft. The tracker this replaces (an
     inherited Hotjar) recorded full session replays into an account Raymond did
     not control; the whole point of building our own is not to repeat that.

     Runs ONCE per page even when several embeds are present. Sends nothing until
     ENDPOINT is set, so the data shape can be proven locally first.
     ========================================================================== */
  (function () {
    if (window.__bopTelemetry) return;          // one collector per page

    var ENDPOINT = 'https://bopaero-telemetry.compilotrc.workers.dev/collect';
    var DEBUG = /[?&]bopdebug=1/.test(location.search);
    var GRID_X = 20, GRID_Y = 40;               // click bins: coarse on purpose
    var MILESTONES = [25, 50, 75, 100];

    var events = [];
    var seenScroll = {};
    var sent = false;

    function ctx() {
      return {
        path: location.pathname,
        view: window.innerWidth <= 900 ? 'phone' : 'desktop'
      };
    }
    function push(type, data) {
      if (events.length >= 200) return;         // bound the payload, always
      events.push({ t: type, d: data || {} });
      if (DEBUG) console.log('[bop:telemetry]', type, data || {});
    }

    /* ── scroll depth ──────────────────────────────────────────────────────
       Milestones rather than a continuous position: it answers "how far do
       visitors get" without describing any individual's path down the page. */
    function scrollDepth() {
      var doc = document.documentElement;
      var max = Math.max(1, doc.scrollHeight - window.innerHeight);
      var pct = Math.min(100, Math.round(((window.scrollY || doc.scrollTop || 0) / max) * 100));
      for (var i = 0; i < MILESTONES.length; i++) {
        var m = MILESTONES[i];
        if (pct >= m && !seenScroll[m]) { seenScroll[m] = 1; push('scroll', { pct: m }); }
      }
    }

    /* ── clicks ────────────────────────────────────────────────────────────
       Position is binned to a 20x40 grid of the DOCUMENT, not exact pixels, so
       the report can draw density without the data describing a precise pointer
       trace. `el` names the control when it is one we care about. */
    function describe(node) {
      var el = node;
      for (var i = 0; i < 6 && el && el.nodeType === 1; i++) {
        if (el.id) return '#' + el.id;
        if (el.getAttribute && el.getAttribute('data-embed')) return '[' + el.getAttribute('data-embed') + ']';
        if (el.tagName === 'A' || el.tagName === 'BUTTON' || el.tagName === 'SELECT') {
          var txt = (el.innerText || el.value || '').trim().replace(/\s+/g, ' ').slice(0, 28);
          return el.tagName.toLowerCase() + (txt ? ':' + txt : '');
        }
        el = el.parentElement;
      }
      return 'other';
    }
    function onClick(e) {
      var doc = document.documentElement;
      var w = Math.max(1, doc.scrollWidth), h = Math.max(1, doc.scrollHeight);
      push('click', {
        x: Math.min(GRID_X - 1, Math.floor((e.pageX / w) * GRID_X)),
        y: Math.min(GRID_Y - 1, Math.floor((e.pageY / h) * GRID_Y)),
        el: describe(e.target)
      });
    }

    /* ── delivery ──────────────────────────────────────────────────────────
       sendBeacon on the way out: it survives navigation, where fetch does not.
       visibilitychange fires on mobile where unload often does not. */
    function flush() {
      if (sent || !events.length) return;
      sent = true;
      scrollDepth();          /* final depth before we stop measuring */
      var payload = { v: 1, ctx: ctx(), events: events };
      if (DEBUG) console.log('[bop:telemetry] FLUSH', JSON.stringify(payload));
      if (!ENDPOINT) return;                    // nothing configured: collect, never send
      try {
        /* text/plain, NOT application/json. A non-safelisted content type forces a
           CORS preflight, and sendBeacon cannot perform one - the browser drops the
           request with no error anywhere. It reported "sent" client-side and nothing
           ever arrived. The body is still JSON; the Worker parses it regardless. */
        var blob = new Blob([JSON.stringify(payload)], { type: 'text/plain;charset=UTF-8' });
        if (!navigator.sendBeacon || !navigator.sendBeacon(ENDPOINT, blob)) {
          fetch(ENDPOINT, { method: 'POST', body: blob, keepalive: true, mode: 'no-cors' });
        }
      } catch (e) { /* telemetry must never break the page */ }
    }

    try {
      window.addEventListener('scroll', scrollDepth, { passive: true });
      /* A low-frequency sampler as well as the scroll listener. Scroll events are
         throttled or suppressed entirely in some contexts - background tabs, some
         webviews, and any automated driver - and depth would then silently never
         record. Sampling is cheap, catches programmatic scrolling too, and stops
         as soon as every milestone is seen or the page is on its way out. */
      var sampler = setInterval(function () {
        scrollDepth();
        if (seenScroll[100]) clearInterval(sampler);
      }, 1000);
      document.addEventListener('click', onClick, true);
      document.addEventListener('visibilitychange', function () {
        if (document.visibilityState === 'hidden') flush();
      });
      window.addEventListener('pagehide', flush);
      scrollDepth();

      window.__bopTelemetry = {
        event: function (name, data) { push(name, data); },
        dump: function () { return { ctx: ctx(), events: events }; }
      };
    } catch (e) {
      window.__bopTelemetry = { event: function () {}, dump: function () { return null; } };
      if (DEBUG) console.warn('[bop:telemetry] disabled:', e.message);
    }
  })();

  /* Leasing Program rates (bopaero.com/sr22t-leasing-program).
   *
   * The rates are the bridge aircraft's lease terms in the SR22T costing — the one
   * place they are edited (private costing editor, /sr22t). Raymond 2026-10-07:
   * the page's typed rates and the costing must not drift apart.
   *
   * The data file's `lease` figures render first (no blank or jump while loading)
   * and stay if the costing can't be reached; tools/sync_costing.py keeps them
   * equal to the costing daily.
   */
  function initLeaseRates(root, spec) {
    var WORDS = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten',
                 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen',
                 'nineteen', 'twenty', 'twenty-one', 'twenty-two', 'twenty-three', 'twenty-four', 'twenty-five',
                 'twenty-six', 'twenty-seven', 'twenty-eight', 'twenty-nine', 'thirty'];
    function money(n) { return '$' + Math.round(n).toLocaleString('en-US'); }
    function words(n) { return WORDS[n] ? WORDS[n] + ' (' + n + ')' : String(n); }
    function set(field, text) {
      Array.prototype.forEach.call(root.querySelectorAll('[data-f="' + field + '"]'), function (el) { el.textContent = text; });
    }
    var FIELDS = ['leaseMonthly', 'leaseIncludedHours', 'leaseExtraHourRate', 'leaseHourlyRate'];
    function usable(l) {
      return l && FIELDS.every(function (f) { return typeof l[f] === 'number' && isFinite(l[f]) && l[f] >= 0; }) &&
             Math.floor(l.leaseIncludedHours) === l.leaseIncludedHours;
    }
    function render(l) {
      set('heading', spec.heading + '');
      set('monthly', money(l.leaseMonthly));
      set('hours', String(l.leaseIncludedHours));
      set('hoursWords', words(l.leaseIncludedHours));
      set('extra', money(l.leaseExtraHourRate));
      set('hourly', money(l.leaseHourlyRate));
    }

    /* The page keeps its two original blocks: rates beside the photo, footnotes
       full-width below. Each block holds a stub naming its part. */
    var host = root.closest ? root.closest('[data-embed]') : null;
    var part = (host && host.getAttribute('data-part')) || '';
    if (part === 'rates') root.querySelector('.bop-lease-notes').hidden = true;
    if (part === 'notes') root.querySelector('.bop-lease-rates').hidden = true;

    if (usable(spec.lease)) render(spec.lease);
    else console.warn('[bopaero:lease-rates] ' + spec.id + ' built-in lease figures are incomplete');

    if (spec.costing && spec.costing.url) {
      /* Minute key: GitHub Pages caches each URL for 10 minutes, so a publish in the
         costing editor shows here within about a minute (same as the calculator). */
      var url = spec.costing.url + (spec.costing.url.indexOf('?') < 0 ? '?' : '&') + 'm=' + Math.floor(Date.now() / 60000);
      fetch(url, { cache: 'no-cache' })
        .then(function (r) { if (!r.ok) throw new Error('costing HTTP ' + r.status); return r.json(); })
        .then(function (c) {
          if (!usable(c && c.bridge)) throw new Error('costing has no complete bridge lease terms');
          render(c.bridge);
        })
        .catch(function (e) {
          console.warn('[bopaero:lease-rates] ' + spec.id + ' live costing unavailable, showing built-in rates:', e.message);
        });
    }
  }

  if (document.readyState === 'loading')
    document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();
